class Solution:
    def myAtoi(self, s: str) -> int:
        INT_MIN, INT_MAX = -2**31, 2**31 - 1
        s = s.lstrip()
        if not s:
            return 0
        sign = 1
        i = 0
        if s[0] in '+-':
            sign = -1 if s[0] == '-' else 1
            i = 1
        digits = []
        while i < len(s) and s[i].isdigit():
            digits.append(s[i])
            i += 1
        if not digits:
            return 0
        value = sign * int(''.join(digits))
        return max(INT_MIN, min(INT_MAX, value))

